def compute(vars):
    old_value = vars["v1"]  # 2018
    new_value = vars["v2"]  # 2019
    value = new_value - old_value
    return {
        "value": value,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
